import random
from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity: int):
        self.cap, self.data = capacity, OrderedDict()  # hash map + doubly linked list
    def get(self, key):
        if key in self.data:
            self.data.move_to_end(key)       # a read also counts as a use
        return self.data.get(key, -1)
    def put(self, key, value):
        self.data[key] = value
        self.data.move_to_end(key)           # also when overwriting a key
        if len(self.data) > self.cap:
            self.data.popitem(last=False)    # evict the least recently used

class RandomizedSet:
    def __init__(self):
        self.items, self.pos = [], {}        # array to pick from, value -> index
    def insert(self, x):
        if x not in self.pos:
            self.pos[x] = len(self.items)
            self.items.append(x)
    def remove(self, x):
        if x in self.pos:
            i, last = self.pos.pop(x), self.items.pop()
            if i < len(self.items):          # x wasn't last: fill its hole
                self.items[i], self.pos[last] = last, i
    def get_random(self):
        return random.choice(self.items)     # uniform, O(1)
